const item = $input.first().json;
let texto = item.output ?? '';

// A confirmação de cadastro de lead nunca deve depender do modelo reproduzir
// um texto verbatim -- mesmo com a instrução "responda EXATAMENTE" no prompt,
// LLMs ocasionalmente parafraseiam, e essa frase é uma promessa concreta pro
// usuário (a equipe vai entrar em contato). Em vez de confiar no texto do
// Agent Leads, detecta via intermediateSteps (precisa de returnIntermediateSteps:
// true habilitado no node do agente) se a tool "Registrar Lead CRM" rodou
// nesse turno e força a resposta certa, disparado ou não pelo modelo -- mesmo
// padrão determinístico das correções abaixo.
const chamouRegistrarLead = Array.isArray(item.intermediateSteps) &&
  item.intermediateSteps.some((s) => s?.action?.tool === 'Registrar Lead CRM');

if (chamouRegistrarLead) {
  texto = 'Seus dados foram registrados! Em breve nossa equipe entrará em contato.';
}

// WhatsApp só reconhece *negrito* (um asterisco) e _itálico_ (um underline).
// O modelo às vezes escreve **negrito**/__itálico__ (markdown padrão) mesmo
// com a instrução no prompt -- corrige aqui de forma determinística, sem
// depender só do modelo obedecer.
texto = texto.replace(/\*\*(.+?)\*\*/g, '*$1*');
texto = texto.replace(/__(.+?)__/g, '_$1_');

// Garante que valor em R$ sempre tenha os centavos (",00") -- o modelo às
// vezes escreve "R$ 500" sem casas decimais.
texto = texto.replace(/R\$\s*\d{1,3}(?:\.\d{3})*(?:,\d{2})?/g, (m) => {
  const numero = m.replace(/^R\$\s*/, '');
  return 'R$ ' + (/,\d{2}$/.test(numero) ? numero : numero + ',00');
});

// WhatsApp reconhece sequências de dígitos (ex.: "870" ou "1.200") como se
// fossem telefone/código e deixa parte do valor sublinhada/colorida, tocável
// -- quebra a sequência com um caractere invisível (zero-width space) logo
// após o primeiro dígito, sem mudar o que aparece pro usuário.
texto = texto.replace(/R\$\s*(\d)(\d{0,2}(?:\.\d{3})*,\d{2})/g, 'R$ $1\u200b$2');

// Remove qualquer divisor de linha inteira ("---" ou o antigo ▬▬▬▬) que o
// modelo ainda tente colocar entre cursos -- o prompt já pede só linha em
// branco entre eles, sem divisor.
texto = texto.replace(/^[ \t]*(-{3,}|▬{3,})[ \t]*\n?/gm, '');

return [{ json: { ...item, output: texto } }];

const data = $input.first().json;
const sel = data.body.listResponseMessage;

const categorias = {
  financeiro: 'financeiro',
  secretaria: 'secretaria',
  ti: 'ti',
  avisos: 'avisos',
  calendario: 'calendario',
  matricula: 'lead_novo',
};

// Os contextos abaixo são lidos pelo agente como se fossem a mensagem do
// usuário. Duas instruções são obrigatórias em todos eles, porque as duas
// falharam com um usuário real logo depois de escolher "Secretaria" no menu:
// (1) o menu JÁ cumprimentou e se apresentou -- o agente cumprimentava de
// novo, com quase o mesmo texto, dois balões seguidos; (2) o agente
// respondia com uma lista de itens soltos ("- Emissão de declarações",
// "- Outro assunto"), que no WhatsApp parece opção clicável: o usuário
// respondeu "Outro assunto" achando que tinha clicado e a conversa andou
// um turno inteiro sem sair do lugar.
const contextos = {
  financeiro: 'O usuário selecionou "Situação financeira" no menu. O menu já cumprimentou e se apresentou -- não cumprimente de novo. Peça direto o CPF para consultar os boletos em aberto.',
  secretaria: 'O usuário selecionou "Secretaria" no menu (assunto de quem já é aluno matriculado). O menu já cumprimentou e se apresentou -- não cumprimente nem se apresente de novo. Pergunte em UMA frase corrida o que ele precisa (documento, declaração, prazo ou situação de matrícula), sem montar lista de opções.',
  ti: 'O usuário selecionou "Suporte TI" no menu. O menu já cumprimentou e se apresentou -- não cumprimente de novo. Pergunte em UMA frase corrida qual problema ele está tendo (acesso ao portal, senha, e-mail ou outro sistema), sem montar lista de opções.',
  avisos: 'O usuário selecionou avisos da escola.',
  calendario: 'O usuário selecionou calendário.',
  matricula: 'O usuário selecionou "Informações de cursos" no menu e demonstrou interesse em se matricular. O menu já cumprimentou e se apresentou. Colete nome completo, email e curso de interesse para registrar o contato.',
};

const categoria = categorias[sel?.selectedRowId] || null;
const mensagem = contextos[sel?.selectedRowId] || `O usuário selecionou: ${sel?.title}`;

return [{ json: { ...data, categoria, body: { ...data.body, text: { message: mensagem } } } }];

const cpfData = $input.first().json;
const webhook = $('Webhook').first().json;
const msg = webhook.body.text.message;

let enriched = msg;
let cpfInfo = null;

if (cpfData.cpf && !cpfData.error && !cpfData.message) {
  cpfInfo = { cpf: cpfData.cpf, tipo: cpfData.tipo || null, nomeResponsavel: cpfData.nomeResponsavel || null, email: cpfData.email || null };
  enriched = `[Sistema: CPF: ${cpfData.cpf}${cpfData.nomeResponsavel ? `, responsável: ${cpfData.nomeResponsavel}` : ''}${cpfData.tipo ? `, tipo: ${cpfData.tipo}` : ''}${cpfData.email ? `, email: ${cpfData.email}` : ''}. Use-o diretamente sem pedir ao usuário, mas NUNCA diga ao usuário que você já sabe o CPF dele nem mencione ter esse dado -- se o assunto não for pagamento/boleto/mensalidade, aja como se não soubesse.]\n\n${msg}`;
}

return [{ json: { ...webhook, cpfInfo, body: { ...webhook.body, text: { message: enriched } } } }];

const cpfData = $input.first().json;
const mapped = $('Mapear Seleção do Menu').first().json;
const msg = mapped.body.text.message;

let enriched = msg;
let cpfInfo = null;

if (cpfData.cpf && !cpfData.error && !cpfData.message) {
  cpfInfo = { cpf: cpfData.cpf, tipo: cpfData.tipo || null, nomeResponsavel: cpfData.nomeResponsavel || null, email: cpfData.email || null };
  enriched = `[Sistema: CPF: ${cpfData.cpf}${cpfData.nomeResponsavel ? `, responsável: ${cpfData.nomeResponsavel}` : ''}${cpfData.tipo ? `, tipo: ${cpfData.tipo}` : ''}${cpfData.email ? `, email: ${cpfData.email}` : ''}. Use-o diretamente sem pedir ao usuário, mas NUNCA diga ao usuário que você já sabe o CPF dele nem mencione ter esse dado -- se o assunto não for pagamento/boleto/mensalidade, aja como se não soubesse.]\n\n${msg}`;
}

return [{ json: { ...mapped, cpfInfo, body: { ...mapped.body, text: { message: enriched } } } }];

