parameters.jsCode:
const item = $input.first().json;
const msg = ($('Webhook').first().json.body?.text?.message || '').toLowerCase();
const tipo = item.cpfInfo?.tipo || null;
const phone = item.body.phone;

let categoria = item.categoria || null; // já vem definida se veio do menu

// Declaração explícita de não-vínculo ("não sou aluno", "ainda não estudo aí")
// é o sinal mais forte de lead que existe, e precisa ser testada ANTES de
// tudo -- inclusive antes da categoria vinda do menu. Sem isso a frase caía
// como "continuação genérica" no classificador de IA, que devolvia a
// categoria anterior e prendia um interessado num atendimento que só serve
// pra quem já é matriculado: foi assim que um lead real ouviu que "esse
// atendimento é específico para quem já está matriculado" e foi mandado
// embora com um link wa.me, em vez de cair no Agent Leads.
const NAO_ALUNO_RE = new RegExp([
  'n[ãa]o\\s+sou\\s+(aluno|aluna|estudante|matriculad)',
  'n[ãa]o\\s+sou\\s+de\\s+voc[êe]s',
  'ainda\\s+n[ãa]o\\s+(sou|estou|estudo)',
  'n[ãa]o\\s+(estou\\s+)?matriculad',
  'n[ãa]o\\s+tenho\\s+matr[íi]cula',
  'n[ãa]o\\s+estudo\\s+(a[íi]|na|no|em)',
  'quero\\s+(ser|virar)\\s+aluno',
  'pretendo\\s+(estudar|me\\s+matricular)',
].join('|'), 'i');

if (NAO_ALUNO_RE.test(msg)) categoria = 'lead_novo';

if (!categoria) {
  const regras = [
    { categoria: 'secretaria', re: /declara[cç][ãa]o|hist[óo]rico escolar|documento|comprovante de matr[íi]cula|transfer[êe]ncia|trancamento|prazo/i },
    { categoria: 'lead_novo', re: /matr[íi]cul|quero (fazer|estudar)|quais (s[ãa]o os )?cursos|todos os cursos|lista(r)? (os )?cursos|mostra(r)? (os )?cursos|ver (os )?cursos|informa[cç][ãa]o.*curso|interessad[oa] (em|no|na)|quero saber sobre o curso|come[çc]ar a estudar|pré[- ]?matr[íi]cula/i },
    { categoria: 'financeiro', re: /boleto|mensalidade|pend[êe]ncia|d[ée]bito|pagar|pagamento|pix|fatura|parcela|vencimento/i },
    { categoria: 'ti', re: /senha|acesso ao portal|login|n[ãa]o consigo entrar|teams|email institucional|sistema fora/i },
    { categoria: 'avisos', re: /\baviso|comunicado|novidade/i },
    { categoria: 'calendario', re: /calend[áa]rio|feriado|pr[óo]xima(s)? (aula|evento|prova)|data d[ae]/i },
    { categoria: 'professor', re: /disciplina|minhas turmas|meus alunos|minhas aulas/i },
  ];
  for (const r of regras) {
    if (r.re.test(msg)) { categoria = r.categoria; break; }
  }
}

// Curso citado pelo nome ou pelo nível ("pós-graduação em farmácia estética",
// "dúvidas sobre a graduação") não batia em regra NENHUMA: o regex de
// lead_novo acima só cobre a palavra "curso" literal e verbos de intenção.
// A frase caía no classificador de IA junto com a categoria anterior e ficava
// presa nela. Fica num teste separado, depois das regras, por ser ambíguo --
// aluno já matriculado também pergunta da própria pós. Por isso só vale
// quando o telefone NÃO está identificado como aluno no cache de CPF; se
// estiver, deixa null de propósito e o classificador de IA desempata olhando
// o histórico.
const CURSO_RE = /p[óo]s[- ]?gradua[çc][ãa]o|gradua[çc][ãa]o|curso livre|\bmba\b|curso de\s+\w|d[úu]vidas?\s+sobre\s+(a|o|as|os)?\s*(curso|p[óo]s|gradua)|saber\s+(mais\s+)?(sobre|d[oa]s?)\s+(a|o|as|os)?\s*(curso|p[óo]s|gradua)|voc[êe]s\s+t[êe]m\s+.{0,25}curso|tem\s+(o\s+)?curso\s+de/i;
if (!categoria && tipo !== 'aluno' && CURSO_RE.test(msg)) categoria = 'lead_novo';

// A guarda de professor (financeiro vs professor sem tipo confirmado, e
// professor vs financeiro) roda uma vez só, DEPOIS que a categoria já passou
// por qualquer caminho -- regra direta ou classificador de IA -- em "Aplicar
// Guarda de Categoria". Não duplica aqui: as duas checagens já moraram nos
// dois lugares ao mesmo tempo, e uma delas ficou pra trás quando a guarda
// virou centralizada -- foi exatamente esse o bug que a suíte de testes
// pegou (professor caindo no financeiro pelo caminho do classificador de IA,
// que não passava por esta função).

// "categoria anterior": só LEITURA aqui, como contexto pro classificador de
// IA decidir se a mensagem atual é uma continuação genérica (ver
// systemMessage do nó "Classificador de Intenção (IA)"). A ESCRITA da
// categoria resolvida mora só em "Aplicar Guarda de Categoria", que roda
// depois da guarda -- gravar aqui, antes da guarda, era o que fazia esse
// cache achar que a conversa "ainda era sobre financeiro" mesmo num turno em
// que um professor tinha acabado de ser bloqueado dali.
const staticData = $getWorkflowStaticData('global');
const sessao = staticData.sessoes && staticData.sessoes[phone];
const agora = Date.now();
const TTL_MS = 30 * 60 * 1000;
const categoriaAnterior = (sessao && sessao.categoria && (agora - sessao.categoriaTs) < TTL_MS) ? sessao.categoria : null;

return [{ json: { ...item, categoria, categoriaAnterior } }];

const raw = (($input.first().json.output) || '').toLowerCase().trim();
const validas = ['financeiro', 'secretaria', 'ti', 'avisos', 'calendario', 'lead_novo', 'professor'];

// match exato (resposta limpa, sem pontuação) tem prioridade -- é o caso esperado
// quando o modelo obedece a instrução de responder só a palavra
const limpo = raw.replace(/[^a-z_À-ú\s]/g, '').trim();
let categoria = validas.includes(limpo) ? limpo : null;

if (!categoria) {
  // fallback pra quando o modelo escreve uma frase em vez de só a palavra: pega a
  // ÚLTIMA categoria válida mencionada (não a primeira por ordem arbitrária do array
  // -- isso já causou um bug real: uma resposta tipo "não é financeiro, é lead_novo"
  // escolhia "financeiro" errado só porque vem primeiro na lista de válidas)
  const palavras = limpo.split(/\s+/);
  for (let i = palavras.length - 1; i >= 0; i--) {
    if (validas.includes(palavras[i])) { categoria = palavras[i]; break; }
  }
}

categoria = categoria || 'outro';

// A escrita da categoria resolvida na sessão do telefone não acontece mais
// aqui -- esse era um segundo ponto de escrita (junto com "Classificar por
// Regra") que gravava a categoria ANTES dela passar pela guarda de
// professor, então podia registrar como certa uma categoria que "Aplicar
// Guarda de Categoria" ia invalidar no mesmo turno. Agora quem grava é só a
// guarda, depois de aplicada -- ver esse nó.
const original = $('Classificar por Regra').first().json;
return [{ json: { ...original, categoria } }];

const item = $input.first().json;
const tipo = item.cpfInfo?.tipo || null;
let categoria = item.categoria || null;

// Guarda centralizada: roda depois que a categoria foi definida por QUALQUER
// caminho (regex direto, sticky-cache, ou classificador de IA) -- nunca
// deixa 'professor' passar sem confirmar tipo === 'professor' no cache, e
// nunca deixa professor cair no financeiro. As duas checagens já moraram
// espalhadas entre este nó e "Classificar por Regra" ao mesmo tempo; um bug
// real (pego pela suíte de testes) veio de uma delas ficar só na metade
// antiga quando este nó foi criado. Agora moram só aqui, as duas.
if (categoria === 'professor' && tipo !== 'professor') categoria = null;
if (categoria === 'financeiro' && tipo === 'professor') categoria = null;

// Único ponto que grava a categoria resolvida na sessão do telefone -- roda
// DEPOIS da guarda acima, pra nunca gravar uma categoria que a guarda acabou
// de invalidar no mesmo turno (isso já deixava o cache achando que a
// conversa "ainda era sobre financeiro" mesmo com um professor barrado ali).
// Só grava quando sobra uma categoria válida: "outro"/null não apaga a
// memória de qual era o último assunto real, pra sobreviver a uma mensagem
// ambígua no meio da conversa.
const staticData = $getWorkflowStaticData('global');
const phone = item.body.phone;
staticData.sessoes = staticData.sessoes || {};
staticData.sessoes[phone] = staticData.sessoes[phone] || {};
const sessao = staticData.sessoes[phone];

// Snapshot de ANTES desta escrita: "Carregar Sessão do Telefone" (próximo nó)
// precisa saber qual era a categoria no INÍCIO deste turno, não a que a
// gente acabou de gravar agora embaixo -- senão toda conversa pareceria "em
// andamento" já na primeira mensagem, porque leria o próprio valor que este
// nó escreveu um instante antes, no mesmo turno.
const categoriaAntesDesteTurno = sessao.categoria || null;
const categoriaAntesDesteTurnoTs = sessao.categoriaTs || null;

if (categoria) {
  sessao.categoria = categoria;
  sessao.categoriaTs = Date.now();
}

return [{ json: { ...item, categoria, categoriaAntesDesteTurno, categoriaAntesDesteTurnoTs } }];

