const body = $input.first().json.body || {};

// Figurinha, reação e áudio de "curtida" são cortesia, não pedido. Responder
// a isso com o aviso de "só entendo texto" reabre do nada um atendimento que
// já tinha se encerrado bem -- foi o que aconteceu com um usuário real que
// mandou uma figurinha de agradecimento depois do "muito obrigado" e recebeu
// de volta um "Olá!" com telefone e e-mail do Financeiro. Ignora em silêncio:
// devolver [] encerra o ramo sem enviar nada.
const ehCortesia = !!(
  body.sticker ||
  body.reaction ||
  body.messageType === 'ReactionMessage' ||
  body.messageType === 'StickerMessage'
);
if (ehCortesia) return [];

// A mensagem não cita mais telefone/e-mail de setor nenhum. O texto antigo
// era fixo no Financeiro ("(11) 99839-3640 / matricula.financeiro@ipessp.edu.br")
// e saía igual em qualquer conversa -- inclusive numa de Secretaria, o que
// deixava o usuário com um contato que não tinha nada a ver com o assunto.
// Quem precisa de humano é encaminhado pelas tools de cada agente, que já
// sabem o setor certo.
const mensagens = [
  'Recebi seu arquivo, mas por aqui eu só consigo ler mensagens de texto. Pode me escrever o que você precisa que eu te ajudo. 😊',
  'Obrigada! Por aqui eu ainda só entendo texto -- me conta por escrito o que você precisa que eu resolvo com você.',
];

return [{
  json: {
    phone: body.phone,
    mensagem: mensagens[Math.floor(Math.random() * mensagens.length)],
  },
}];

// Grava no histórico paralelo da sessão do telefone (lido por "Carregar
// Sessão do Telefone") o que foi enviado fora de qualquer agente. Sem isso o
// agente do próximo turno não sabe que este aviso saiu: um usuário real
// respondeu "É texto mesmo" logo depois dele e a Eliza, sem contexto nenhum,
// concordou com uma frase que nunca tinha dito ("Sim, é texto mesmo!").
const phone = $('Webhook').first().json.body.phone;
const texto = $('Avaliar Mídia Recebida').first().json.mensagem;

const staticData = $getWorkflowStaticData('global');
staticData.sessoes = staticData.sessoes || {};
staticData.sessoes[phone] = staticData.sessoes[phone] || {};
const sessao = staticData.sessoes[phone];
const agora = Date.now();
const TTL_ENVIOS = 30 * 60 * 1000;

const lista = (sessao.envios || []).filter((e) => (agora - e.ts) < TTL_ENVIOS);
lista.push({ texto: `Aviso automático (mídia não suportada): "${texto}"`, ts: agora });
sessao.envios = lista.slice(-3);

return [{ json: { ok: true } }];

// Mesmo histórico paralelo do aviso de mídia (sessao.envios): o menu é
// enviado por um nó HTTP solto, sem agente, e por isso não entrava em
// memória nenhuma. O agente que atendia a opção escolhida achava que era a
// primeira mensagem da conversa e mandava uma segunda saudação, quase
// idêntica à do menu, dois balões seguidos.
const phone = $('Webhook').first().json.body.phone;

const staticData = $getWorkflowStaticData('global');
staticData.sessoes = staticData.sessoes || {};
staticData.sessoes[phone] = staticData.sessoes[phone] || {};
const sessao = staticData.sessoes[phone];
const agora = Date.now();
const TTL_ENVIOS = 30 * 60 * 1000;

const lista = (sessao.envios || []).filter((e) => (agora - e.ts) < TTL_ENVIOS);
lista.push({
  texto: 'Menu principal: saudação "Olá! Sou a Eliza, assistente virtual do IPESSP" + lista de opções (cursos, financeiro, secretaria, TI, avisos, calendário). A pessoa JÁ foi cumprimentada e você JÁ se apresentou.',
  ts: agora,
});
sessao.envios = lista.slice(-3);

return [{ json: { ok: true } }];

const item = $input.first().json;
const phone = item.body.phone;
const agora = Date.now();

// Sessão única por telefone -- um só objeto guardado em static data, em vez
// dos quatro caches paralelos que existiam antes (categorias/atendimentos/
// envios/leadsSaudados), cada um com sua própria cópia da mesma lógica de
// "filtra se (agora - ts) < TTL". A categoria em si é escrita só em "Aplicar
// Guarda de Categoria"; este nó só lê e complementa com o que é específico
// da conversa (transferência de setor, envios automáticos, saudação da
// triagem).
const staticData = $getWorkflowStaticData('global');
staticData.sessoes = staticData.sessoes || {};
staticData.sessoes[phone] = staticData.sessoes[phone] || {};
const sessao = staticData.sessoes[phone];

// --- Continuidade da conversa entre setores -------------------------------
// Janela bem mais larga que o sticky de classificação (6h, não 30min): serve
// só pra avisar o agente novo que está pegando uma conversa em andamento,
// não pra reclassificar nada. Usa o snapshot que "Aplicar Guarda de
// Categoria" tirou ANTES de escrever a categoria deste turno -- não
// sessao.categoria direto, que a esta altura já é o valor deste mesmo turno
// (ver comentário lá).
const TTL_CONVERSA = 6 * 60 * 60 * 1000;
const conversaEmAndamento = !!(item.categoriaAntesDesteTurno && (agora - item.categoriaAntesDesteTurnoTs) < TTL_CONVERSA);
const setorAnterior = conversaEmAndamento ? item.categoriaAntesDesteTurno : null;

// --- Mensagens enviadas fora de qualquer agente ---------------------------
// O menu inicial e o aviso de "só entendo texto" saem por nós HTTP soltos,
// sem passar por agente nenhum -- então nunca entravam na memória. Os nós
// "Registrar Envio Automático (...)" gravam esses envios em sessao.envios e
// este nó devolve como contexto pro próximo turno.
const TTL_ENVIOS = 30 * 60 * 1000;
const envios = (sessao.envios || []).filter((e) => (agora - e.ts) < TTL_ENVIOS);
sessao.envios = envios;

// --- Boas-vindas da triagem de novos alunos -------------------------------
// Manda o texto fixo de boas-vindas só na primeira vez por telefone, com
// folga de 12h -- não mais "sem histórico anterior", que deixou de fazer
// sentido desde que a memória virou compartilhada entre setores (quem chega
// transferido da Secretaria já TEM histórico, mas nunca recebeu a abertura).
const TTL_SAUDACAO = 12 * 60 * 60 * 1000;
const jaSaudado = !!(sessao.saudadoLeadsTs && (agora - sessao.saudadoLeadsTs) < TTL_SAUDACAO);

let instrucaoBoasVindasLeads = '';
if (item.categoria === 'lead_novo') {
  sessao.saudadoLeadsTs = agora;
  if (jaSaudado) {
    instrucaoBoasVindasLeads = 'Esta pessoa JÁ recebeu o texto de boas-vindas da triagem -- NÃO envie de novo. Continue de onde a conversa parou e peça só os dados que ainda faltam.';
  } else if (conversaEmAndamento) {
    instrucaoBoasVindasLeads = 'Esta pessoa acabou de ser transferida de outro atendimento, então a conversa já está em andamento: NÃO envie o texto de boas-vindas nem se apresente de novo. Faça uma ponte de uma frase ("posso te ajudar com isso") e peça, em seguida, nome completo, e-mail e curso de interesse -- pulando o que ela já tiver informado no histórico.';
  } else {
    instrucaoBoasVindasLeads = 'Esta é a primeira mensagem desta pessoa na triagem de novos alunos: comece enviando o texto de boas-vindas abaixo, exatamente como está.';
  }
}

return [{ json: { ...item, setorAnterior, envios, instrucaoBoasVindasLeads } }];

const item = $input.first().json;

// Preâmbulo único, compartilhado pelos 5 agentes (Financeiro/Secretaria/TI/
// Leads/Professor) -- antes esse bloco (persona, regras de formatação
// WhatsApp, anti-alucinação, privacidade de CPF/CRM, telefones de fallback)
// estava colado igual em cada um dos 5 systemMessage. Um só ponto de edição;
// cada agente só define seu texto específico e referencia {{ $json.preambulo
// }} no início do próprio systemMessage.
//
// Este nó é só texto: não lê nem grava static data -- isso é
// "Carregar Sessão do Telefone", que roda antes e entrega setorAnterior/
// envios/instrucaoBoasVindasLeads prontos.
const TELEFONE_SECRETARIA = '5511997738431';
const TELEFONE_TI = '5511919237687';
const TELEFONE_FINANCEIRO = '5511998393640';

const blocoEnvios = item.envios.length
  ? `\n\nMENSAGENS AUTOMÁTICAS QUE O SISTEMA JÁ MANDOU PRA ESTA PESSOA (ela recebeu, mas não estão no histórico da conversa -- considere-as ditas por você, não repita e não contradiga):\n${item.envios.map((e) => `- ${e.texto}`).join('\n')}`
  : '';

const blocoTransferencia = (item.setorAnterior && item.setorAnterior !== item.categoria)
  ? `\n\nESTA CONVERSA VEIO TRANSFERIDA do atendimento de ${item.setorAnterior} -- ela já estava em andamento. Leia o histórico antes de responder: não se apresente de novo e não peça nada que a pessoa já tenha informado.`
  : '';

const preambulo = `Você é "Eliza", assistente virtual do IPESSP no WhatsApp. Seja cordial, objetiva e profissional -- nunca use gírias ("tô", "cê", "e aí", "blz").

FORMATAÇÃO WHATSAPP (não é markdown padrão): negrito usa UM asterisco de cada lado, tipo *assim* -- nunca **assim** com dois. Itálico é _assim_, com um underline. Não use #, ##, nem blocos de código.
Listas: um item por linha começando com "- " ou um emoji, com uma linha em branco entre cada item.
Formate valores em R$ e datas no padrão brasileiro. Respostas curtas.

Só cumprimente ("Olá", se apresentar como Eliza) se esta for de fato a primeira mensagem trocada com a pessoa. Se já existir histórico nesta conversa, ou uma mensagem automática listada abaixo, vá direto ao ponto -- repetir a apresentação a cada turno faz o atendimento parecer que reiniciou.

Nunca escreva suas sugestões como se fossem opções de um menu clicável (lista curta de itens soltos, um por linha). No WhatsApp o usuário responde repetindo o item -- ele acha que clicou -- e a conversa trava. Pergunte em frase corrida.

O histórico desta conversa pode conter trechos atendidos por outro setor. Use como contexto, mas responda só o que é do seu escopo.

Nunca invente informação -- use só dados retornados pelas tools. Nunca mencione nenhum código/ID interno retornado pelas tools ("codigo", "codigoBoleto" etc.) -- refira-se pela descrição/data, nunca pelo número solto.

Nunca use as palavras "CRM" ou "lead" com o usuário, nem diga que ele "já está registrado/cadastrado" de uma conversa anterior -- fale como se fosse a primeira vez que ele procura a gente, mesmo que internamente já exista um registro. Isso vale só pros registros dos nossos sistemas: o histórico DESTA conversa você usa normalmente.

Se a mensagem trouxer um trecho "[Sistema: CPF: ...]", é um dado pré-identificado só pra seu uso interno -- nunca confirme, mencione ou mostre esse CPF ao usuário (nem mascarado).

Se a dúvida estiver fora do que você resolve aqui, direcione: Secretaria wa.me/${TELEFONE_SECRETARIA} · TI/Suporte wa.me/${TELEFONE_TI} · Financeiro wa.me/${TELEFONE_FINANCEIRO}.
NUNCA use esses números para quem ainda NÃO é aluno e quer conhecer cursos ou se matricular: novos alunos são atendidos aqui mesmo, pelo próprio bot. Mandar um interessado embora com um link wa.me é perder a matrícula -- nenhum desses três números é "atendimento de novos alunos".${blocoTransferencia}${blocoEnvios}`;

return [{ json: { ...item, preambulo } }];
